sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var assignment = gs.getProperty('x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs');
    var emailTask = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
    emailTask.swb_id = current.swb_id;
    emailTask.queue_name = gs.getProperty("HSBC_QueueName_email case task");
    emailTask.parent = current.sys_id;
    emailTask.qtrack_id = current.qtrack_id;
    emailTask.task_type = "SWB Maker Activities";
    emailTask.assignment_group = assignment;
    //MSSRBXCE-307-343 TNR smartlink response requires different email task short description
    if (current.description.includes('ACTION REQUIRED - CTM Allocation pending - Unmatched trade - Trade not recognised') || current.description.includes('FOLLOW UP - CTM Allocation pending - Unmatched trade - Trade not recognised'))
        emailTask.short_description = 'Perform SWB mapping for unmatched trade - Client doesn\'t recognise';
    else
        emailTask.short_description = 'Perform Maker Activities for Email with QTRACK ID: ' + current.qtrack_id;

    emailTask.insert();

})(current, previous);
